public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    // Attempt to use the built‑in formatted message if available
    try {
        // Some logging frameworks expose a getFormattedMessage() method
        java.lang.reflect.Method m = event.getClass().getMethod("getFormattedMessage");
        Object result = m.invoke(event);
        if (result instanceof String) {
            return (String) result;
        }
    } catch (Throwable ignored) {
        // Fallback to getMessage()
    }
    // Default to just the raw message
    return event.getMessage();
}

public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    java.util.Date date = new java.util.Date(event.getTimeStamp());
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    String timestamp = sdf.format(date);
    String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
    String logger = event.getLoggerName() != null ? event.getLoggerName() : "NO-LOGGER";
    String message = event.getFormattedMessage() != null ? event.getFormattedMessage() : "";
    return timestamp + " " + level + " " + logger + " - " + message;
}

public String format(LoggingEvent event){
    // Simple formatting based on a fixed pattern: "%d [%t] %-5p %c - %m%n"
    // Date formatting
    java.util.Calendar cal = java.util.Calendar.getInstance();
    cal.setTimeInMillis(event.getTimestamp());
    int year = cal.get(java.util.Calendar.YEAR);
    int month = cal.get(java.util.Calendar.MONTH) + 1;
    int day = cal.get(java.util.Calendar.DAY_OF_MONTH);
    int hour = cal.get(java.util.Calendar.HOUR_OF_DAY);
    int minute = cal.get(java.util.Calendar.MINUTE);
    int second = cal.get(java.util.Calendar.SECOND);
    int millis = cal.get(java.util.Calendar.MILLISECOND);
    String date = String.format("%04d-%02d-%02d %02d:%02d:%02d.%03d",
            year, month, day, hour, minute, second, millis);
    // Level padded to 5 characters
    String level = event.getLevel().toString();
    if (level.length() < 5) {
        level = String.format("%-" + 5 + "s", level);
    }
    // Retrieve other event data
    String thread = event.getThreadName();
    String logger = event.getLoggerName();
    String message = event.getMessage();
    // Construct formatted string
    return String.format("%s [%s] %s %s - %s%n",
            date, thread, level, logger, message);
}

