    if (event == null) return "";
    try{
        java.lang.reflect.Method m = event.getClass().getMethod("getFormattedMessage");
        Object val = m.invoke(event);
        return val != null ? val.toString() : "";
    }catch (Exception e){
        try{
            java.lang.reflect.Method m = event.getClass().getMethod("getMessage");
