    int index = headerPart.indexOf("\r\n", end);
    return index;  // returns -1 if no CRLF sequence is found
}

private int parseEndOfLine(String headerPart, int end){
    // Find the next CRLF sequence starting from the given position
    int idx = headerPart.indexOf("\r\n", end);
    // If CRLF not found, return the end of the string as the line end
    return idx == -1 ? headerPart.length() : idx;
}

private int parseEndOfLine(String headerPart, int end) {
    int crlf = headerPart.indexOf("\r\n", end);
    if (crlf >= 0) {
        return crlf;
    }
    // Fallback to lone line feed only
    int lf = headerPart.indexOf('\n', end);
    if (lf >= 0) {
        return lf;
    }
    // No line terminator found – return length to indicate end of string
    return headerPart.length();
}

private int parseEndOfLine(String headerPart,int end){
    // Scan forward from the current index until we encounter a CRLF sequence.
    // Return the index of the '\r' that starts the sequence.
    // If no CRLF is found, return -1 to indicate the line was not terminated.
    for(int i = end; i < headerPart.length() - 1; i++){
        if(headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n'){
            return i;
        }
    }
    return -1;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < -1 || end >= headerPart.length()) {
        return -1;
    }
    int i = end + 1;
    while (i < headerPart.length() - 1) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
        i++;
    }
    return -1;
}

