public static <V, E> IsomorphicGraphMapping<V, E> identity(Graph<V, E> graph) {
    return new IsomorphicGraphMapping<>(graph, graph, v -> v, e -> e);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    java.util.Map<V,V> vertexMap = new java.util.HashMap<>();
    for(V v : graph.vertexSet()){
        vertexMap.put(v, v);
    }
    return new IsomorphicGraphMapping<>(graph, graph, vertexMap);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    // Create an empty mapping
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>();
    // Map each vertex to itself
    for (V vertex : graph.vertexSet()){
        mapping.mapVertex(vertex, vertex);
    }
    // Map each edge to itself
    for (E edge : graph.edgeSet()){
        mapping.mapEdge(edge, edge);
    }
    return mapping;
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    return new IsomorphicGraphMapping<>(graph, graph);
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
    IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<>(graph, graph);
    for (V v : graph.vertexSet()){
        mapping.setVertexMapping(v, v);
    }
    for (E e : graph.edgeSet()){
        mapping.setEdgeMapping(e, e);
    }
    return mapping;
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
    }
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    // synchronized block to guard against concurrent access
    synchronized (FADE_LOCK) {
        collectForDeletion(file);
        if (!FADE_HOOK_REGISTERED) {
            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                for (File f : FADE_FILES) {
                    if (f.exists() && !f.delete()) {
                        // Ignore failures silently; callers are not notified
                    }
                }
            }));
            FADE_HOOK_REGISTERED = true;
        }
    }
}

/* ---------- internal state ---------- */
private static final List<File> FADE_FILES = new ArrayList<>();
private static boolean FADE_HOOK_REGISTERED = false;
private static final Object FADE_LOCK = new Object();

/* ---------- helpers ---------- */
private static void collectForDeletion(File file) {
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children != null) {
            for (File child : children) {
                collectForDeletion(child);
            }
        }
    }
    FADE_FILES.add(file);
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        return; // nothing to schedule
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                forceDeleteOnExit(f);
            }
        }
    }
    // Register the file (or directory) for deletion on JVM exit.
    // deleteOnExit() does not throw IOException; if an exception occurs it
    // will be thrown as an unchecked SecurityException or will be silently
    // ignored by the JVM implementation.
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    if (!file.exists()) {
        return;
    }
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files == null) {
            throw new IOException("Unable to list contents of directory: " + file);
        }
        for (File f : files) {
            forceDeleteOnExit(f);
        }
    }
    try {
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Failed to schedule deletion on exit for: " + file, e);
    }
}

