@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    // Add vertices that are not yet in the target graph
    for(V v : resultMap.values()){
        if(!target.containsVertex(v)){
            target.addVertex(v);
        }
    }
    // Partition vertices into two sets assuming keys start with 'L' or 'R'
    java.util.Set<V> left = new java.util.LinkedHashSet<>();
    java.util.Set<V> right = new java.util.LinkedHashSet<>();
    for(java.util.Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        if(key != null && (key.startsWith("L") || key.startsWith("l"))){
            left.add(entry.getValue());
        }else if(key != null && (key.startsWith("R") || key.startsWith("r"))){
            right.add(entry.getValue());
        }
    }
    // If the key pattern didn't yield two partitions, split the vertices arbitrarily
    if(left.isEmpty() || right.isEmpty()){
        java.util.List<V> list = new java.util.ArrayList<>(resultMap.values());
        int mid = list.size() / 2;
        left.clear();
        right.clear();
        left.addAll(list.subList(0, mid));
        right.addAll(list.subList(mid, list.size()));
    }
    // Connect every vertex in left to every vertex in right
    for(V u : left){
        for(V v : right){
            if(!target.containsEdge(u, v)){
                target.addEdge(u, v);
            }
        }
    }
}

