public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // number of vertices in each part
    int leftSize = 3;
    int rightSize = 3;

    // lists to keep the created vertices
    List<V> leftVertices = new ArrayList<>();
    List<V> rightVertices = new ArrayList<>();

    // create left part vertices and store them in resultMap with keys "L0", "L1", ...
    for (int i = 0; i < leftSize; i++) {
        String key = "L" + i;
        V vertex = target.addVertex();
        target.addVertex(vertex);
        resultMap.put(key, vertex);
        leftVertices.add(vertex);
    }

    // create right part vertices and store them in resultMap with keys "R0", "R1", ...
    for (int i = 0; i < rightSize; i++) {
        String key = "R" + i;
        V vertex = target.addVertex();
        target.addVertex(vertex);
        resultMap.put(key, vertex);
        rightVertices.add(vertex);
    }

    // add all possible edges between left and right part vertices
    for (V lv : leftVertices) {
        for (V rv : rightVertices) {
            target.addEdge(lv, rv);
        }
    }
}

