public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Create a CodedOutputStream backed by the provided OutputStream
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out);
    // Compute the size of the serialized message
    int size = schema.getSerializedSize(message, buffer);
    // Write the length as a varint prefix
    codedOut.writeRawVarint32(size);
    // Serialize the message itself
    schema.writeTo(message, codedOut, buffer);
    // Flush any buffered data to the underlying stream
    codedOut.flush();
    // Return the size of the serialized message
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the size of the message in bytes
    int size = schema.getMessageSize(message);
    // Create a coded output stream backed by the given OutputStream
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    // Write the size as a varint prefix
    cos.writeUInt32NoTag(size);
    // Serialize the message to the coded stream
    schema.serialize(message, cos, buffer);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    // Write the size as a varint
    int v = size;
    while ((v & ~0x7F) != 0) {
        out.write((v & 0x7F) | 0x80);
        v >>>= 7;
    }
    out.write(v);
    // Serialize the message itself
    schema.writeTo(message, out, buffer);
    return size;
