public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // If the provided type is not a ParameterizedType, we cannot resolve arguments.
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] actualTypes = paramType.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualTypes.length];

    for (int i = 0; i < actualTypes.length; i++) {
        Class<?> resolved = resolveType(actualTypes[i], targetType);
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }

    return result;
}

/**
 * Attempts to resolve a {@link Type} to a concrete {@link Class}.
 * <p>
 * The resolution follows these rules:
 * <ul>
 *   <li>If the type is a {@link Class}, it is returned as-is.</li>
 *   <li>If the type is a {@link ParameterizedType}, the raw type is returned.</li>
 *   <li>If the type is a {@link WildcardType}, its upper bound is used for resolution.</li>
 *   <li>For a {@link TypeVariable} we try to resolve through the provided
 *       {@code targetType} hierarchy. If a mapping cannot be found, {@code null}
 *       is returned.</li>
 *   <li>Any other kind of type results in {@code null}.</li>
 * </ul>
 *
 * @param t the type to resolve
 * @param target the class whose type variable bindings might help resolve
 * @return the concrete Class, or {@code null} if it cannot be resolved
 */
private static Class<?> resolveType(Type t, Class<?> target) {
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    } else if (t instanceof ParameterizedType) {
        Type raw = ((ParameterizedType) t).getRawType();
        if (raw instanceof Class<?>) {
            return (Class<?>) raw;
        }
    } else if (t instanceof WildcardType) {
        Type[] ub = ((WildcardType) t).getUpperBounds();
        if (ub.length == 1) {
            return resolveType(ub[0], target);
        }
    } else if (t instanceof TypeVariable<?>) {
        // Attempt to resolve a type variable from the target type's hierarchy.
        // Build a mapping from type variable to actual type by walking the
        // target's type hierarchy.
        Map<TypeVariable<?>, Type> mapping = new HashMap<>();
        buildTypeVariableMapping(target, mapping);
        Type replacement = mapping.get(t);
        if (replacement != null) {
            return resolveType(replacement, target);
        }
    }
    return null;
}

/**
 * Builds a mapping from {@link TypeVariable} of {@code cls} to the actual {@link Type}
 * that should be used to replace it within the given class hierarchy.
 *
 * @param cls the class to inspect
 * @param map a map to populate with type variable replacements
 */
private static void buildTypeVariableMapping(Class<?> cls, Map<TypeVariable<?>, Type> map) {
    // Process superclass
    Type superType = cls.getGenericSuperclass();
    processType(superType, map);
    // Process interfaces
    for (Type itfc : cls.getGenericInterfaces()) {
        processType(itfc, map);
    }
}

