public Mappings diffStructure(String tableName, Mappings mappings) {
    // Retrieve the current mapping for the given table name
    Mappings current = getCurrentMappings(tableName);
    if (current == null) {
        // If there's no current mapping, return an empty Mappings instance
        return new Mappings();
    }

    // Extract the properties section from both the current and historical mappings
    java.util.Map<String, Object> currentProps =
            (java.util.Map<String, Object>) current.toMap().get("properties");
    java.util.Map<String, Object> historyProps =
            (java.util.Map<String, Object>) mappings.toMap().get("properties");

    // Prepare a map to hold the diff of new fields
    java.util.Map<String, Object> diffProps = new java.util.HashMap<>();

    // Iterate over the historical properties and keep only those that do not exist
    // in the current mapping, while skipping the "_source" config
    for (String field : historyProps.keySet()) {
        if (!"_source".equals(field) && !currentProps.containsKey(field)) {
            diffProps.put(field, historyProps.get(field));
        }
    }

    // Construct the resulting diff mapping
    java.util.Map<String, Object> diffMap = new java.util.HashMap<>();
    diffMap.put("properties", diffProps);

    return new Mappings(diffMap);
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        // Retrieve the current mapping of the index
        GetMappingsRequest getMappingRequest = new GetMappingsRequest();
        getMappingRequest.indices(tableName);
        GetMappingsResponse getMappingResponse = client.indices().getMapping(getMappingRequest, RequestOptions.DEFAULT);
        Map<String, MappingMetadata> map = getMappingResponse.mappings();

        // If the index does not exist or has no mapping, return empty diff
        if (!map.containsKey(tableName)) {
            return new Mappings(Collections.emptyMap());
        }

        // Current mapping source
        MappingMetadata currentMeta = map.get(tableName);
        Map<String, Object> currentSource = currentMeta.getSourceAsMap();

        // Fields (properties) of the current mapping
        Map<String, Object> currentProps = safeCastMap(currentSource.get("properties"));

        // Fields (properties) of the history (input) mapping
        Map<String, Object> inputProps = safeCastMap(mappings.getSourceAsMap().get("properties"));

        // Compute fields that exist in current but not in input
        Set<String> diffFieldNames = new HashSet<>();
        if (currentProps != null) {
            diffFieldNames.addAll(currentProps.keySet());
        }
        if (inputProps != null) {
            diffFieldNames.removeAll(inputProps.keySet());
        }

        // Build the diff properties map
        Map<String, Object> diffProps = new LinkedHashMap<>();
        for (String field : diffFieldNames) {
            diffProps.put(field, currentProps.get(field));
        }

        // Prepare the final diff mapping (exclude _source)
        Map<String, Object> diffSource = new HashMap<>();
        diffSource.put("properties", diffProps);

        return new Mappings(diffSource);
    } catch (Exception e) {
        throw new RuntimeException("Failed to compute diff mapping for table: " + tableName, e);
    }
}

/** Helper to safely cast an object to a Map<String,Object> */
@SuppressWarnings("unchecked")
private Map<String, Object> safeCastMap(Object obj) {
    if (obj instanceof Map) {
        return (Map<String, Object>) obj;
    }
    return Collections.emptyMap();
}

public Mappings diffStructure(String tableName, Mappings mappings){
    // Return early if either mapping is null to avoid NullPointerException
    if (mappings == null || tableName == null) {
        return new Mappings();
    }

    // Obtain the current mapping for the specified table. The exact method to fetch
    // the current mapping will depend on the surrounding code base. Here we assume
    // there is a helper that fetches the mapping from the index. If such helper
    // does not exist, replace the following line with the appropriate call.
    Mappings currentMappings = MappingsUtils.getMappingFromIndex(tableName);
    if (currentMappings == null) {
        return new Mappings();
    }

    // Fetch the property definitions from both mappings
    Map<String, Object> currentProps = currentMappings.getProperties();
    Map<String, Object> historyProps = mappings.getProperties();

    // Prepare a map to hold fields that are new in the current mapping
    Map<String, Object> diffProps = new HashMap<>();

    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String fieldName = entry.getKey();
        // Skip the predefined _source field as requested
        if ("_source".equals(fieldName)) {
            continue;
        }
        // If the field is not present in the history mapping, add it to the diff
        if (!historyProps.containsKey(fieldName)) {
            diffProps.put(fieldName, entry.getValue());
        }
    }

    // Build a new Mappings instance containing only the differences
    Mappings diffMappings = new Mappings();
    diffMappings.setProperties(diffProps);
    return diffMappings;
}

public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return Mappings.EMPTY;
    }
    try {
        /* Retrieve current mapping from Elasticsearch. */
        GetMappingRequest getRequest = new GetMappingRequest(tableName);
        GetMappingResponse getResponse = client.indices().getMapping(getRequest, RequestOptions.DEFAULT);
        Map<String, Object> currentSource = getResponse.mappings().get(tableName).getSourceAsMap();
        Map<String, Object> historySource = mappings.getSourceAsMap();

        /* Build sets of field names for comparison. */
        Set<String> currentFields = currentSource.keySet();
        Set<String> historyFields = historySource.keySet();

        /* Identify fields that exist in current mapping but not in history mapping. */
        Set<String> newFields = new HashSet<>(currentFields);
        newFields.removeAll(historyFields);

        /* Construct a map containing only the new fields. */
        Map<String, Object> diff = new LinkedHashMap<>();
        for (String field : newFields) {
            diff.put(field, currentSource.get(field));
        }

        /* Remove the _source configuration to avoid index update conflicts. */
        diff.remove("_source");

        return diff.isEmpty() ? Mappings.EMPTY : new Mappings(diff);
    } catch (Exception e) {
        log.warn("Failed to diff mapping structure for index {}: {}", tableName, e.getMessage());
        return Mappings.EMPTY;
    }
}

public void addNewTarget(Channels channels,IConsumer consumer){
    if(channels==null || consumer==null){
        return;
    }
    try {
        // Try a direct add by a known method name
        java.lang.reflect.Method addMethod = channels.getClass().getMethod("addConsumer", IConsumer.class);
        addMethod.invoke(channels, consumer);
    } catch (Exception e) {
        // Fallback: try to access a list of consumers via get/set methods
        try {
            java.lang.reflect.Method getMethod = channels.getClass().getMethod("getConsumers");
            java.util.List<?> list = (java.util.List<?>) getMethod.invoke(channels);
            if (list == null) {
                // Try to initialize a new list and set it
                try {
                    java.lang.reflect.Method setMethod = channels.getClass().getMethod("setConsumers", java.util.List.class);
                    java.util.List<IConsumer> newList = new java.util.ArrayList<>();
                    setMethod.invoke(channels, newList);
                    list = newList;
                } catch (Exception inner) {
                    // Cannot set list, abort
                    return;
                }
            }
            if (list != null) {
                //noinspection unchecked
                ((java.util.List<IConsumer>) list).add(consumer);
            }
        } catch (Exception inner) {
            // Last resort: ignore if nothing else works
        }
    }
}

