public static void createConfigurationDirectory() {
    String osName = System.getProperty("os.name");
    String basePath;

    if (osName != null && osName.startsWith("Windows") && osName.contains("2000")) {
        // On Windows 2000 machines, create the directory under Documents and Settings
        String drive = System.getenv("HOMEDRIVE");
        String path = System.getenv("HOMEPATH");
        if (drive == null) drive = "";
        if (path == null) path = "";
        basePath = drive + path;
        if (basePath.isEmpty()) {
            // Fallback to user.home if environment variables are not set
            basePath = System.getProperty("user.home");
        }
    } else {
        // For all other platforms, use user.home
        basePath = System.getProperty("user.home");
    }

    if (basePath == null || basePath.isEmpty()) {
        // If user.home is not available, abort silently
        return;
    }

    java.io.File configDir = new java.io.File(basePath, "lf5");
    if (!configDir.exists()) {
        configDir.mkdirs();
    }
}

