public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    // Telnet-friendly line termination (CRLF)
    final String telnetMsg = message + "\r\n";
    // Assume there is a collection of PrintWriters named `clientWriters`
    for (PrintWriter out : clientWriters) {
        try {
            out.print(telnetMsg);
            out.flush();
        } catch (Exception e) {
            // If sending fails, we can handle or ignore
            // e.g., log the error or mark the client for removal
        }
    }
}

public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    final String output = message + "\r\n";
    List<Socket> toRemove = new ArrayList<>();
    for (Socket socket : clientSockets) {
        try {
            OutputStream os = socket.getOutputStream();
            os.write(output.getBytes());
            os.flush();
        } catch (IOException e) {
            toRemove.add(socket);
        }
    }
    for (Socket s : toRemove) {
        try {
            s.close();
        } catch (IOException ignore) {}
        clientSockets.remove(s);
    }
}

