public synchronized void send(final String message){
    // Ensure CRLF line endings for telnet compatibility
    String telnetMsg = (message == null ? "" : message) + "\r\n";
    for (PrintWriter writer : clients) {
        writer.print(telnetMsg);
        writer.flush();
    }
}

public synchronized void send(final String message) {
    String telnetMsg = message + "\r\n";
    for (Object client : clients) {
        try {
            if (client instanceof java.io.PrintWriter) {
                java.io.PrintWriter out = (java.io.PrintWriter) client;
                out.print(telnetMsg);
                out.flush();
            } else if (client instanceof java.net.Socket) {
                java.net.Socket s = (java.net.Socket) client;
                java.io.OutputStream out = s.getOutputStream();
                out.write(telnetMsg.getBytes());
                out.flush();
            } else {
                try {
                    client.getClass().getMethod("sendMessage", String.class).invoke(client, telnetMsg);
                } catch (NoSuchMethodException e) {
                    client.getClass().getMethod("write", String.class).invoke(client, telnetMsg);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

