public void put(LoggingEvent o){
    // Attempt to add to the buffer; silently ignore if the buffer is full
    buffer.offer(o);
}

public void put(LoggingEvent o) {
    if (o == null) {
        return;
    }
    // If the buffer is already full, drop the event silently.
    if (count == capacity) {
        return;
    }
    array[writeIndex] = o;
    writeIndex = (writeIndex + 1) % capacity;
    count++;
}

public void put(LoggingEvent o){
    int pos = this.writeIndex;
    this.buffer[pos] = o;
    pos++;
    if (pos == this.buffer.length) {
        pos = 0;
    }
    this.writeIndex = pos;
}

public void put(LoggingEvent o) {
    // The caller guarantees that the buffer has space; so just insert.
    buffer[tail] = o;
    tail = (tail + 1) & mask; // wrap around using mask
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new java.util.ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    long step = FETCH_DATA_DURATION;  // assume this constant is defined elsewhere
    long current = start;
    while (current < end) {
        long next = current + step;
        if (next > end) {
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long segmentEnd;
        if (remaining <= FETCH_DATA_DURATION) {
            segmentEnd = end;
        } else {
            segmentEnd = current + FETCH_DATA_DURATION;
        }
        ranges.add(new TimeRange(current, segmentEnd));
        current = segmentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end || FETCH_DATA_DURATION <= 0) {
        return ranges;
    }
    long cursor = start;
    while (cursor < end) {
        long next = cursor + FETCH_DATA_DURATION;
        if (next > end) {
            next = end;
        }
        ranges.add(new TimeRange(cursor, next));
        cursor = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> timeRanges = new ArrayList<>();
    if (start >= end) {
        return timeRanges;
    }
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next > end || next < current) {
            next = end;
        }
        timeRanges.add(new TimeRange(current, next));
        current = next;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0 || start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

