static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    long year = timeBucket / 10000;
    long month = (timeBucket % 10000) / 100;
    long day = timeBucket % 100;
    long startDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + startDay;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        return timeBucket;
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    // Ensure the new day is within the month bounds
    if (newDay > 31) {
        newDay = 31;
    }

    return year * 10000L + month * 100L + newDay;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    // Extract year, month and day from the time bucket (assumed format YYYYMMDD)
    long year  = timeBucket / 10000L;
    long month = (timeBucket / 100L) % 100L;
    long day   = timeBucket % 100L;

    // Guard against invalid dayStep values
    if(dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }

    // Calculate the start day of the bucket that contains the current day
    long startDay = ((day - 1) / dayStep) * dayStep + 1;

    // Return the compressed bucket as YYYYMMDD
    return year * 10000L + month * 100L + startDay;
}

