    return year * 10000L + month * 100L + startDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    final int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen || index + len > strLen) {
        throw new IndexOutOfBoundsException("Index or length out of bounds");
    }
    int end = index + len;
    int size = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        // Check for surrogate pair
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            // UTF-8 requires 4 bytes for a supplementary character
            size += 4;
            i += 2;
            continue;
        }
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else {
            // Covers BMP characters as well as lone surrogates
            size += 3;
        }
        i++;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str is null");
    }
    int strLen = str.length();
    if (index < 0 || len < 0 || index + len > strLen) {
        throw new IndexOutOfBoundsException("index + len out of bounds");
    }
    int size = 0;
    int end = index + len;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i++);
        if (ch < 0x80) { // 1-byte
            size += 1;
        } else if (ch < 0x800) { // 2-byte
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i < end && Character.isLowSurrogate(str.charAt(i))) {
                // valid surrogate pair -> 4-byte UTF-8
                size += 4;
                i++; // consume low surrogate
            } else {
                // unmatched high surrogate, treat as 3-byte sequence
                size += 3;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // unmatched low surrogate, treat as 3-byte sequence
            size += 3;
        } else { // 3-byte
            size += 3;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) throw new NullPointerException("str");
    if (len < 0) throw new IllegalArgumentException("len must be non-negative");
    int end = index + len;
    if (index < 0 || end > str.length()) throw new IndexOutOfBoundsException("index/len out of range");
    int size = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
            i += 1;
        } else if (ch < 0x800) {
            size += 2;
            i += 1;
        } else {
            // check for surrogate pair
            if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // code point > U+10000
                i += 2;
            } else {
                size += 3;
                i += 1;
            }
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else {
            if (Character.isHighSurrogate(c)) {
                // Possible surrogate pair
                if (i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                    // Valid surrogate pair -> 4 bytes
                    size += 4;
                    i++; // Skip low surrogate
                } else {
                    // Lone high surrogate -> encode as 3 bytes as per UTF-8 replacement logic
                    size += 3;
                }
            } else if (Character.isLowSurrogate(c)) {
                // Lone low surrogate -> encode as 3 bytes
                size += 3;
            } else {
                // BMP character that needs 3 bytes
                size += 3;
            }
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0) return 0;
    int end = index + len;
    if (end > str.length()) end = str.length(); // clamp to length to avoid IndexOutOfBounds
    int size = 0;
    for (int i = index; i < end; ) {
        char c = str.charAt(i);
        int cp;
        if (Character.isHighSurrogate(c) && (i + 1) < end) {
            char c2 = str.charAt(i + 1);
            if (Character.isLowSurrogate(c2)) {
                cp = Character.toCodePoint(c, c2);
                i += 2;
            } else {
                // unmatched high surrogate, encode replacement character
                cp = 0xFFFD;
                i++;
            }
        } else if (Character.isLowSurrogate(c)) {
            // unmatched low surrogate
            cp = 0xFFFD;
            i++;
        } else {
            cp = c;
            i++;
        }

        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

