public boolean remove(int val){
    if (!valToIndex.containsKey(val)) return false;
    int index = valToIndex.get(val);
    int lastVal = entries.get(entries.size() - 1);
    entries.set(index, lastVal);
    valToIndex.put(lastVal, index);
    entries.remove(entries.size() - 1);
    valToIndex.remove(val);
    return true;
}

public boolean remove(int val){
    int bucketIdx = Math.abs(val) % SIZE;
    List<Integer> bucket = buckets[bucketIdx];
    if (bucket == null) return false;
    Iterator<Integer> it = bucket.iterator();
    while (it.hasNext()){
        if (it.next() == val){
            it.remove();
            return true;
        }
    }
    return false;
}

public boolean remove(int val) {
    Integer idxObj = valToIndex.get(val);
    if (idxObj == null) return false;
    int idx = idxObj;
    int last = vals.get(vals.size() - 1);
    vals.set(idx, last);
    if (last != val) {
        valToIndex.put(last, idx);
    }
    vals.remove(vals.size() - 1);
    valToIndex.remove(val);
    return true;
}

public static boolean startsWithIgnoreCase(String str, String prefix) {
    if (str == null || prefix == null) {
        return false;
    }
    int prefixLen = prefix.length();
    if (prefixLen == 0) {
        return true;
    }
    if (str.length() < prefixLen) {
        return false;
    }
    return str.regionMatches(true, 0, prefix, 0, prefixLen);
}

