private static String substitute(String value, Properties props, java.util.Set<String> seen) {
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}\\s]+)\\}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    StringBuffer sb = new StringBuffer();
    while (matcher.find()) {
        String var = matcher.group(1);
        if (seen.contains(var)) { // avoid infinite recursion
            matcher.appendReplacement(sb, Matcher.quoteReplacement("${" + var + "}"));
            continue;
        }
        String replacement = props.getProperty(var);
        if (replacement == null) {
            matcher.appendReplacement(sb, Matcher.quoteReplacement("${" + var + "}"));
        } else {
            seen.add(var);
            replacement = substitute(replacement, props, seen);
            seen.remove(var);
            matcher.appendReplacement(sb, Matcher.quoteReplacement(replacement));
        }
    }
    matcher.appendTail(sb);
    return sb.toString();
}

