private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Handle nulls: if both are null, return true; if str is null and suffix not null, return false
    if (str == null) {
        return suffix == null;
    }
    // If suffix is null, consider it as a match (empty suffix)
    if (suffix == null) {
