    Set<E> edgeSet = targetMap.computeIfAbsent(targetVertex, k -> new HashSet<>());
    edgeSet.add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    if (sourceVertex == null || targetVertex == null || e == null) {
        return;
    }
    // Initialize nested map for source vertex if absent
    Map<V, Set<E>> targetMap = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());
    // Initialize set of edges for target vertex if absent
    Set<E> edges = targetMap.computeIfAbsent(targetVertex, k -> new HashSet<>());
    // Add the edge to the set
    edges.add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Use a two‑level map to store all edges between vertex pairs.
    // Assume there is an instance field:
    //     Map<V, Map<V, Collection<E>>> index;
    Map<V, java.util.Collection<E>> targetMap =
            index.computeIfAbsent(sourceVertex, k -> new java.util.HashMap<>());
    java.util.Collection<E> edges =
            targetMap.computeIfAbsent(targetVertex, k -> new java.util.HashSet<>());
    edges.add(e);
}

protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Ensure the index map exists
    if (index == null) {
        index = new HashMap<>();
    }
    // Add entry for source -> target
    Map<V, E> targets = index.computeIfAbsent(sourceVertex, k -> new HashMap<>());
    targets.put(targetVertex, e);
    // If the graph is undirected, add reverse entry as well
    Map<V, E> reverseTargets = index.computeIfAbsent(targetVertex, k -> new HashMap<>());
    reverseTargets.put(sourceVertex, e);
}

