    double xMin = box.getMinX();
    double xMax = box.getMaxX();
    double yMin = box.getMinY();
    double yMax = box.getMaxY();

    // Compute the midpoint along the X‑axis.
    double midX = (xMin + xMax) / 2.0;

    // Construct the two new boxes that share the same Y‑range
    // and split the X‑range evenly.
    Box2D left  = new Box2D(xMin, yMin, midX, yMax);
    Box2D right = new Box2D(midX, yMin, xMax, yMax);

    // Return both boxes in a pair.
    return new Pair<>(left, right);
}

