}

private void enlarge(final int size){
    // Ensure the internal byte array can hold the current size plus the requested additional space.
    int required = this.size + size;          // 'size' is the current number of bytes used
    if (required <= buffer.length) {
        return; // No need to enlarge
    }
    // Compute a new capacity, at least double the current or the required size, whichever is larger.
    int newCapacity = Math.max(buffer.length << 1, required);
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(buffer, 0, newBuffer, 0, this.size);
    buffer = newBuffer;
}

private void enlarge(final int size){
    if(size <= 0) return;
    byte[] old = this.bytes;
    int newCap = old.length + size;
    byte[] newBytes = new byte[newCap];
    System.arraycopy(old, 0, newBytes, 0, old.length);
    this.bytes = newBytes;
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    int required = this.len + size;
    if (required <= buffer.length) {
        return;
    }
    int newCap = buffer.length == 0 ? size : buffer.length * 2;
    while (newCap < required) {
        newCap *= 2;
    }
    byte[] tmp = new byte[newCap];
    System.arraycopy(buffer, 0, tmp, 0, len);
    buffer = tmp;
}

private void enlarge(final int size) {
    int needed = this.length + size;
    if (needed <= buffer.length) {
        return;
    }
    int newCapacity = Math.max(buffer.length << 1, needed);
    byte[] tmp = new byte[newCapacity];
    System.arraycopy(buffer, 0, tmp, 0, length);
    buffer = tmp;
}

private void enlarge(final int size) {
    if (data == null) {
        data = new byte[size];
        count = 0;
        return;
    }
    int currentCapacity = data.length;
    int needed = count + size;
    int newCapacity = currentCapacity * 2;
    if (newCapacity < needed) {
        newCapacity = needed;
    }
    byte[] newData = new byte[newCapacity];
    System.arraycopy(data, 0, newData, 0, count);
    data = newData;
}

