    if (o1 == null) {
        return (o2 == null) ? 0 : -1;
    }
    if (o2 == null) {
        return 1;
    }
    return Double.compare(o1, o2);
}

@Override public int compare(Double o1, Double o2){
    if (o1 == null && o2 == null) return 0;
    if (o1 == null) return -1;
    if (o2 == null) return 1;
    int c = Double.compare(o1, o2);
    return c == 0 ? 0 : (c < 0 ? -1 : 1);
}

