    if (o1 == null && o2 == null) return 0;
    if (o1 == null) return -1;
    if (o2 == null) return 1;
    return Double.compare(o1.doubleValue(), o2.doubleValue());
}

@Override
public int compare(Double o1, Double o2) {
    // Handle nulls if they occur, otherwise compare numeric values
    if (o1 == null) {
        if (o2 == null) {
            return 0; // both null, considered equal
        }
        return -1; // null is considered less than any non-null value
    }
    if (o2 == null) {
        return 1; // any non-null value is greater than null
    }
    int cmp = Double.compare(o1, o2);
    if (cmp < 0) {
        return -1;
    } else if (cmp > 0) {
        return 1;
    } else {
        return 0;
    }
}

