public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    while (node != null) {
        // Write the content of the current buffer segment
        out.write(node.buf, 0, node.pos);
        // Accumulate the number of bytes written
        total += node.pos;
        // Move to the next buffer segment
        node = node.next;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int total = 0;
    for (LinkedBuffer cur = node; cur != null; cur = cur.next) {
        out.write(cur.buf, 0, cur.end);
        total += cur.end;
    }
    return total;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer current = node;
    while (current != null) {
        out.write(current.buf, 0, current.pos);
        totalSize += current.pos;
        current = current.next;
    }
    return totalSize;
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    LinkedBuffer curr = node;
    while (curr != null) {
        byte[] buf = curr.getBuffer();
        int start = curr.getStart();
        int len = curr.getLength();
        if (buf != null && len > 0) {
            out.write(buf, start, len);
            totalSize += len;
        }
        curr = curr.getNext();
    }
    return totalSize;
}

