public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    StringBuilder sb = new StringBuilder();
    sb.append(sdf.format(new java.util.Date(event.getTimeStamp()))).append(' ');
    sb.append(event.getLevel()).append(' ');
    sb.append(event.getLoggerName()).append(" - ");
    Object messageObj = event.getMessage();
    if (messageObj != null) {
        if (messageObj instanceof Object[]) {
            Object[] params = (Object[]) messageObj;
            if (params.length > 0 && params[0] instanceof String) {
                String pattern = (String) params[0];
                Object[] args = java.util.Arrays.copyOfRange(params, 1, params.length);
                try {
                    sb.append(java.lang.String.format(pattern, args));
                } catch (Exception e) {
                    sb.append(pattern);
                    sb.append(" [").append(java.util.Arrays.toString(args)).append(']');
                }
            } else {
                sb.append(java.util.Arrays.toString(params));
            }
        } else {
            sb.append(messageObj.toString());
        }
    }
    if (event.getThrowableInformation() != null) {
        sb.append(System.lineSeparator());
        java.io.StringWriter sw = new java.io.StringWriter();
        java.io.PrintWriter pw = new java.io.PrintWriter(sw);
        event.getThrowableInformation().getThrowable().printStackTrace(pw);
        pw.flush();
        sb.append(sw.toString());
    }
    return sb.toString();
}

public String format(final LoggingEvent event){
    if(event == null){
        return "";
    }
    String message;
    try{
        message = event.getFormattedMessage();
    }catch(Throwable t){
        Object msgObj = event.getMessage();
        message = (msgObj != null) ? msgObj.toString() : "";
    }
    java.util.Date date = new java.util.Date(event.getTimeStamp());
    return String.format("%1$tF %1$tT [%2$s] %3$s - %4$s", date, event.getLevel(), event.getLoggerName(), message);
}

public String format(final LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    sb.append('[').append(event.getTimeStamp()).append("] ");
    sb.append(event.getLevel()).append(" ");
    sb.append(event.getThreadName()).append(" ");
    sb.append(event.getLoggerName()).append(" - ");
    sb.append(event.getRenderedMessage());
    if(event.getThrowableInformation()!=null){
        sb.append(System.lineSeparator());
        String[] trace = event.getThrowableInformation().getThrowableStrRep();
        if(trace!=null){
            for(String line: trace){
                sb.append(line).append(System.lineSeparator());
            }
        }
    }
    sb.append(System.lineSeparator());
    return sb.toString();
}

public String format(final LoggingEvent event){
    if(event == null){
        return "";
    }
    // Date formatting
    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
    String timestamp = sdf.format(new java.util.Date(event.getTimeStamp()));

    String level = event.getLevel() != null ? event.getLevel().toString() : "";
    String thread = event.getThreadName() != null ? event.getThreadName() : "";
    String logger = event.getLoggerName() != null ? event.getLoggerName() : "";
    String message = event.getRenderedMessage() != null ? event.getRenderedMessage() : "";

    // Throwable stack trace if present
    String throwable = "";
    if(event.getThrowableInformation() != null){
        java.lang.Throwable th = event.getThrowableInformation().getThrowable();
        if(th != null){
            java.io.StringWriter sw = new java.io.StringWriter();
            java.io.PrintWriter pw = new java.io.PrintWriter(sw);
            th.printStackTrace(pw);
            pw.flush();
            throwable = sw.toString();
        }
    }

    // Build final formatted string
    StringBuilder sb = new StringBuilder();
    sb.append("[")
      .append(timestamp)
      .append("] [")
      .append(level)
      .append("] [")
      .append(thread)
      .append("] [")
      .append(logger)
      .append("] - ")
      .append(message);
    if(!throwable.isEmpty()){
        sb.append(System.lineSeparator());
        sb.append(throwable);
    }
    return sb.toString();
}

public String format(final LoggingEvent event){
    StringBuilder sb = new StringBuilder();
    sb.append(event.getTimeStamp())
      .append(" [")
      .append(event.getLevel())
      .append("] [")
      .append(event.getThreadName())
      .append("] ")
      .append(event.getLoggerName())
      .append(" - ")
      .append(event.getMessage());
    Throwable t = event.getThrowable();
    if(t != null){
        sb.append(System.lineSeparator());
        sb.append(t.toString());
        for(StackTraceElement ste : t.getStackTrace()){
            sb.append(System.lineSeparator());
            sb.append("\tat ").append(ste.toString());
        }
    }
    return sb.toString();
}

