private void putAbstractTypes(final int start, final int end){
    for(int i = start; i < end; i++){
        int tag = currentFrame[i];
        stackMapTableEntries.putByte(tag);
        if(tag == 7){ // OBJECT
            int classInfo = currentFrame[i+1];
            stackMapTableEntries.putShort(classInfo);
            i++;
        } else if(tag == 8){ // UNINITIALIZED
            int offset = currentFrame[i+1];
            stackMapTableEntries.putShort(offset);
            i++;
        }
        // other tags (0-6) have no additional data
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        int tag = type.getTag();
        stackMapTableEntries.add((byte) tag);
        switch (tag) {
            case 7: // OBJECT
                int classInfoIndex = type.getClassIndex();
                stackMapTableEntries.add((byte) (classInfoIndex >>> 8));
                stackMapTableEntries.add((byte) (classInfoIndex & 0xFF));
                break;
            case 8: // UNHANDLED
                int offset = type.getOffset();
                stackMapTableEntries.add((byte) (offset >>> 8));
                stackMapTableEntries.add((byte) (offset & 0xFF));
                break;
            default:
                // For tags 0-6, no additional data is required
                break;
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];
        byte tag = type.getVerificationTag();
        stackMapTableEntries.add(tag);
        switch (tag) {
            case 7: // object_type
            case 8: // uninitialized_this
                int cpIndex = type.getConstantPoolIndex();
                stackMapTableEntries.add((byte) ((cpIndex >> 8) & 0xFF));
                stackMapTableEntries.add((byte) (cpIndex & 0xFF));
                break;
            case 9: // uninitialized
                int offset = type.getOffset();
                stackMapTableEntries.add((byte) ((offset >> 8) & 0xFF));
                stackMapTableEntries.add((byte) (offset & 0xFF));
                break;
            default:
                // primitive and top types require no additional bytes
                break;
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame.get(i);
        VerificationTypeInfo vti = type.toVerificationTypeInfo();
        stackMapTableEntries.add(vti);
    }
}

