    this.buffer = baos.toByteArray();
    // Reset the read pointer to the start
    this.readPointer = 0;
}

public void readFrom(final InputStream in) throws IOException {
    // Reset the read pointer to the start of the buffer.
    position = 0;
    // Read all bytes from the input stream.
    ByteArrayOutputStream buffer = new ByteArrayOutputStream();
    byte[] chunk = new byte[8192];
    int length;
    while ((length = in.read(chunk)) != -1) {
        buffer.write(chunk, 0, length);
    }
    byte[] data = buffer.toByteArray();
    // Ensure the internal storage is large enough.
    if (storage == null || storage.length < data.length) {
        storage = new byte[data.length];
    }
    // Copy the read data into the internal buffer.
    System.arraycopy(data, 0, storage, 0, data.length);
    limit = data.length;
}

