@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == null) {
        throw new Exception("Target type cannot be null");
    }
    if (!Character.class.equals(type) && !char.class.equals(type)) {
        throw new Exception("Unsupported target type: " + type.getName());
    }
    if (value == null) {
        return null;
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.isEmpty()) {
            throw new Exception("Cannot convert empty string to Character");
        }
        return s.charAt(0);
    }
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return (char) intValue;
    }
    throw new Exception("Cannot convert type " + value.getClass().getName() + " to Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Only support conversion to java.lang.Character or primitive char
    if (type != Character.class && type != char.class) {
        throw new Exception("Unsupported target type: " + type.getName());
    }

    if (value == null) {
        return null;
    }

    // If the value is already a Character, simply return it
    if (value instanceof Character) {
        return value;
    }

    // If the value is a String, attempt to use its single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0); // autoboxed to Character
        } else {
            throw new Exception("Cannot convert String of length " + str.length()
                    + " to a single Character");
        }
    }

    // If the value is a Number, cast its int value to a char
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return (char) intValue; // autoboxed to Character
    }

    // Fallback: attempt to use value's toString representation
    String s = value.toString();
    if (s.length() == 1) {
        return s.charAt(0);
    }

    throw new Exception("Cannot convert value of type "
            + value.getClass().getName() + " (" + value + ") to a Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }

    // Ensure the target type is Character or primitive char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException(
                "Target type must be java.lang.Character or char, but was " + type.getName());
    }

    if (value instanceof Character) {
        return value;
    }

    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException(
                    "Cannot convert String to Character: string length must be 1 but was " + str.length());
        }
    }

    if (value instanceof Number) {
        // Convert the numeric value to an int and then to a char
        return (char) ((Number) value).intValue();
    }

    throw new IllegalArgumentException(
            "Cannot convert value of type " + value.getClass().getName() + " to java.lang.Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Handle null value
    if (value == null) {
        return null;
    }
    if (type == null) {
        throw new IllegalArgumentException("Target type cannot be null");
    }

    // Only perform conversion when the requested type is Character or primitive char
    if (Character.class.isAssignableFrom(type) || type == char.class) {
        if (value instanceof Character) {
            return value; // Already a Character instance
        }
        if (value instanceof Number) {
            // Convert numeric types to their char representation using the int value
            return Character.valueOf((char) ((Number) value).intValue());
        }
        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return Character.valueOf(str.charAt(0));
            } else {
                throw new Exception("Cannot convert String of length " + str.length() + " to a Character.");
            }
        }
        throw new Exception("Unsupported source type for conversion to Character: " + value.getClass().getName());
    }
    // If the requested type is not Character, simply return the value unchanged
    return value;
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Handle null values: primitive char cannot accept null
    if (value == null) {
        if (type == char.class) {
            throw new IllegalArgumentException("Cannot convert null to primitive char");
        }
        return null;
    }
    // Only support conversion when the target type is Character or char
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }
    // Already a Character instance
    if (value instanceof Character) {
        return value;
    }
    // Numbers can be cast to char using their integer value
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return (char) intValue;
    }
    // Strings of length 1 can be converted to a single character
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: string length != 1");
        }
    }
    // Any other type is unsupported
    throw new IllegalArgumentException(
        "Cannot convert value of type " + value.getClass().getName() + " to Character");
}

