public static int nextPrime(int desiredCapacity) {
    int capacity = Math.max(desiredCapacity, 2);
    if (capacity <= 3) return 3;
    if (capacity % 2 == 0) capacity++;           // Make it odd
    int limit = capacity;
    if (desiredCapacity >= 1000) {
        limit = (int)Math.floor(desiredCapacity * 1.11);
        if (limit < capacity) limit = capacity;
    }
    while (true) {
        if (isPrime(capacity)) return capacity;
        capacity += 2;                           // Next odd number
        if (desiredCapacity >= 1000 && capacity > limit) {
            // Typically a prime exists within the 11% range; if not, continue searching.
        }
        if (capacity < 0) {                       // Overflow protection
            return Integer.MAX_VALUE;
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 == 0 || n % 3 == 0) return false;
    for (int i = 5; (long)i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) return false;
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Make the candidate odd to reduce checks
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate = desiredCapacity == 2 ? 2 : candidate + 1;
    }
    while (!isPrime(candidate)) {
        candidate += 2;
        // In very rare case of overflow, wrap to a reasonable number
        if (candidate < 0) {
            candidate = Integer.MAX_VALUE - 3; // last odd number before overflow
            while (!isPrime(candidate) && candidate > 0) {
                candidate -= 2;
            }
            break;
        }
    }
    return candidate;
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n == 2 || n == 3) {
        return true;
    }
    if (n % 2 == 0) {
        return false;
    }
    int limit = (int) Math.sqrt(n);
    for (int i = 3; i <= limit; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 1) return 2;
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        if (candidate == 2) return 2;
        candidate++; // make it odd
    }
    while (true) {
        boolean isPrime = true;
        if (candidate == 2 || candidate == 3) {
            isPrime = true;
        } else {
            if (candidate % 2 == 0 || candidate % 3 == 0) {
                isPrime = false;
            } else {
                for (int i = 5; i * i <= candidate; i += 6) {
                    if (candidate % i == 0 || candidate % (i + 2) == 0) {
                        isPrime = false;
                        break;
                    }
                }
            }
        }
        if (isPrime) return candidate;
        candidate += 2; // skip even numbers
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    // If candidate is even and greater than 2, make it odd
    if (candidate > 2 && (candidate & 1) == 0) {
        candidate++;
    }
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Skip even numbers
        candidate += 2;
        // Prevent overflow of candidate in case we reach near Integer.MAX_VALUE
        if (candidate <= 0) {
            return Integer.MAX_VALUE;
        }
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if ((n & 1) == 0 || n % 3 == 0) {
        return false;
    }
    int limit = (int) Math.sqrt(n);
    for (int i = 5; i <= limit; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) return 2;
    int n = desiredCapacity;
    // Make n odd to skip even numbers
    if ((n & 1) == 0) n++;
    while (true) {
        boolean prime = true;
        // Quick checks for small primes
        if (n == 2) return 2;
        if (n % 2 == 0) prime = false;
        else {
            int limit = (int) Math.sqrt(n);
            for (int i = 3; i <= limit; i += 2) {
                if (n % i == 0) {
                    prime = false;
                    break;
                }
            }
        }
        if (prime) return n;
        n += 2;
    }
}

