public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder out = new StringBuilder(str.length());
    char[] chars = str.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char ch = chars[i];
        if (ch != '\\') {
            out.append(ch);
            continue;
        }
        // Handle escape
        if (i + 1 >= chars.length) {
            throw new IllegalArgumentException("Trailing backslash at end of string");
        }
        char next = chars[++i];
        switch (next) {
            case 'b': out.append('\b'); break;
            case 't': out.append('\t'); break;
            case 'n': out.append('\n'); break;
            case 'f': out.append('\f'); break;
            case 'r': out.append('\r'); break;
            case '\"': out.append('\"'); break;
            case '\'': out.append('\''); break;
            case '\\': out.append('\\'); break;
            case 'u':
                // Unicode escape \uXXXX
                if (i + 4 >= chars.length) {
                    throw new IllegalArgumentException("Invalid Unicode escape sequence");
                }
                String hex = "" + chars[++i] + chars[++i] + chars[++i] + chars[++i];
                try {
                    int code = Integer.parseInt(hex, 16);
                    out.append((char) code);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid Unicode escape: \\u" + hex, e);
                }
                break;
            default:
                // Octal escape \nnn (1-3 digits)
                if (next >= '0' && next <= '7') {
                    int val = next - '0';
                    // Consume up to two more octal digits
                    for (int j = 0; j < 2 && i + 1 < chars.length && chars[i + 1] >= '0' && chars[i + 1] <= '7'; j++) {
                        val = (val << 3) + (chars[++i] - '0');
                    }
                    out.append((char) val);
                } else {
                    // Unsupported escape, keep as-is
                    out.append('\\').append(next);
                }
        }
    }
    return out.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder(str.length());
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) { // backslash at end of string
                result.append('\\');
                continue;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    result.append('\n');
                    i++;
                    break;
                case 't':
                    result.append('\t');
                    i++;
                    break;
                case 'r':
                    result.append('\r');
                    i++;
                    break;
                case 'b':
                    result.append('\b');
                    i++;
                    break;
                case 'f':
                    result.append('\f');
                    i++;
                    break;
                case '\"':
                    result.append('\"');
                    i++;
                    break;
                case '\'':
                    result.append('\'');
                    i++;
                    break;
                case '\\':
                    result.append('\\');
                    i++;
                    break;
                case 'u': // Unicode escape \uXXXX
                    if (i + 5 < str.length()) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            result.append((char) code);
                            i += 5; // consumed \uXXXX
                        } catch (NumberFormatException e) {
                            // Malformed unicode, keep as is
                            result.append('\\').append('u');
                            i++;
                        }
                    } else {
                        result.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    // Octal escape \0 to \777
                    if (Character.isDigit(next)) {
                        int j = i + 1;
                        int end = Math.min(str.length(), i + 4); // at most 3 digits
                        StringBuilder oct = new StringBuilder();
                        while (j < end && Character.isDigit(str.charAt(j)) && oct.length() < 3) {
                            oct.append(str.charAt(j));
                            j++;
                        }
                        try {
                            int val = Integer.parseInt(oct.toString(), 8);
                            result.append((char) val);
                            i = j - 1;
                        } catch (NumberFormatException e) {
                            result.append('\\').append(next);
                            i++;
                        }
                    } else {
                        // Unknown escape, keep literal
                        result.append('\\').append(next);
                        i++;
                    }
                    break;
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

private static String javaCharset(String charset){
    if(charset == null){
        throw new IllegalArgumentException("charset cannot be null");
    }
    java.util.Map<String, java.nio.charset.Charset> map = java.nio.charset.Charset.availableCharsets();
    for(java.nio.charset.Charset cs : map.values()){
        if(cs.name().equalsIgnoreCase(charset)){
            return cs.name();
        }
        for(String alias : cs.aliases()){
            if(alias.equalsIgnoreCase(charset)){
                return cs.name();
            }
        }
    }
    return charset;
}

