protected int removeUnusedNodes() {
    // Assume there is a field named 'root' of type Category
    if (root == null) {
        return 0;
    }
    return removeInactiveRecursive(root);
}

private int removeInactiveRecursive(Category node) {
    int removedCount = 0;
    java.util.List<Category> children = node.getChildren();
    // Iterate from end to start to safely remove items from the list
    for (int i = children.size() - 1; i >= 0; i--) {
        Category child = children.get(i);
        removedCount += removeInactiveRecursive(child);
        if (!child.isActive()) {
            children.remove(i);
            removedCount++;
        }
    }
    return removedCount;
}

protected int removeUnusedNodes() {
    int removed = 0;
    if (categories == null) {
        return 0;
    }
    Iterator<Category> rootIter = categories.iterator();
    while (rootIter.hasNext()) {
        Category root = rootIter.next();
        if (!root.isActive()) {
            rootIter.remove();
            removed++;
        } else {
            removed += removeFromChildren(root);
        }
    }
    return removed;
}

private int removeFromChildren(Category parent) {
    int count = 0;
    List<Category> children = parent.getChildren();
    if (children == null) {
        return 0;
    }
    Iterator<Category> iter = children.iterator();
    while (iter.hasNext()) {
        Category child = iter.next();
        if (!child.isActive()) {
            iter.remove();
            count++;
        } else {
            count += removeFromChildren(child);
        }
    }
    return count;
}

protected int removeUnusedNodes() {
    if (root == null) {
        return 0;
    }
    int removedCount = 0;
    // If the root itself is inactive, delete the whole tree
    if (!root.active) {
        removedCount = countNodes(root);
        root = null;
        return removedCount;
    }
    // Otherwise, traverse children and remove inactive nodes
    removedCount += removeFromChildren(root);
    return removedCount;
}

private int removeFromChildren(Node parent) {
    int removed = 0;
    // iterate backwards to safely remove entries from the list
    for (int i = parent.children.size() - 1; i >= 0; i--) {
        Node child = parent.children.get(i);
        if (!child.active) {
            removed += countNodes(child);
            parent.children.remove(i);
        } else {
            removed += removeFromChildren(child);
        }
    }
    return removed;
}

private int countNodes(Node node) {
    int count = 1; // count this node
    for (Node child : node.children) {
        count += countNodes(child);
    }
    return count;
}

