            int b2 = classFileBuffer[offset++] & 0xFF;
            charBuffer[dst++] = (char)(((b & 0x1F) << 6) | (b2 & 0x3F));
        } else if ((b & 0xF0) == 0xE0) {
            int b2 = classFileBuffer[offset++] & 0xFF;
            int b3 = classFileBuffer[offset++] & 0xFF;
            charBuffer[dst++] = (char)(((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F));
        } else {
            throw new IllegalArgumentException("Malformed modified UTF-8 at constant pool index "+constantPoolEntryIndex);
        }
    }
    return new String(charBuffer, 0, dst);
}

