private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // If the start node itself is the stop node, return immediately.
    if (circ.getNode().equals(stop)) {
        return circ;
    }
    // Traverse along the outer face in the specified direction until we either
    // encounter a node that satisfies the predicate or we reach the stop node.
    while (!circ.getNode().equals(stop) && !predicate.test(circ.getNode())) {
        circ.next();
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    if (predicate.test(circ.getNode())) {
        return circ;
    }
    while (!circ.getNode().equals(stop)) {
        circ.next();                     // advance to the next vertex on the outer face
        if (predicate.test(circ.getNode())) {
            return circ;
        }
    }
    return circ;                         // reached the stop node without matching the predicate
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Start from the given node. If it satisfies the predicate, we return immediately.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start);
    }

    // Traverse the outer face in the specified direction until we hit the stop node.
    Node current = start;
    while (!current.equals(stop)) {
        // Move to the next or previous node on the outer face depending on the direction.
        current = dir > 0 ? current.getNextOuterFace() : current.getPrevOuterFace();

        // If this node satisfies the predicate, we return a circulator pointing at it.
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
    }

    // If no node satisfying the predicate was found, return a circulator at the stop node.
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator starting from the specified node and direction
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);

    // If the start node is already the stop node, return it (after checking the predicate)
    if (start.equals(stop)) {
        // It is acceptable to return the start node whether or not the predicate matches,
        // since the method contract says "or to the stop node"
        return circulator;
    }

    // Traverse the outer face until the stop node is reached
    while (!circulator.getNode().equals(stop)) {
        // If the current node satisfies the predicate, return this circulator
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
        // Move to the next node along the outer face
        circulator = circulator.next();
    }

    // The stop node was reached; return the circulator pointing to it
    return circulator;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node cannot be null");
    }

    Node current = start;

    // Return immediately if the starting node already satisfies the predicate
    if (predicate.test(current)) {
        return new OuterFaceCirculator(current);
    }

    // Traverse along the outer face
    while (true) {
        // Move to the next node in the specified direction
        current = current.getNextInOuterFace(dir);

        // Stop if we reach the boundary stop node or loop back to the start
        if (current == stop || current == start) {
            break;
        }

        // If the current node satisfies the predicate, return a circulator for it
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
    }

    // No node satisfying the predicate was found; return circulator to the stop node
    return new OuterFaceCirculator(stop);
}

