    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IndexOutOfBoundsException(
                "byteOffset and byteLength must refer to a valid range in the source array");
        }
    }

    // Ensure sufficient capacity
    ensureCapacity(length + byteLength);

    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, byteArray, length, byteLength);
