}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative");
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException(
                    "byteOffset (" + byteOffset + ") out of bounds for array of length " + byteArrayValue.length);
        }
        if (byteLength > byteArrayValue.length - byteOffset) {
            throw new IndexOutOfBoundsException(
                    "byteLength (" + byteLength + ") plus byteOffset (" + byteOffset + ") exceeds array length "
                            + byteArrayValue.length);
        }
        if (byteLength > 0) {
            ensureSize(size + byteLength);
            System.arraycopy(byteArrayValue, byteOffset, buf, size, byteLength);
            size += byteLength;
        }
    } else {
        // put null bytes (i.e., zeros)
        if (byteLength > 0) {
            ensureSize(size + byteLength);
            for (int i = 0; i < byteLength; i++) {
                buf[size + i] = 0;
            }
            size += byteLength;
        }
    }
    return this;
}

