    if (indices == null || indices.isEmpty()) {
        return;
    }
    Collections.sort(indices);
    for (int i = 0; i < indices.size(); i++) {
        if (indices.get(i) != i) {
            throw new IllegalStateException(
                "Sharding key indices are not continuous for model '"
                    + modelName + "': " + indices);
        }
    }
}

private void check(String modelName) throws IllegalStateException {
    List<ShardingKey> keys = ShardingKeyRegistry.getShardingKeys(modelName);
    if (keys == null || keys.isEmpty()) {
        return; // no sharding keys to validate
    }
    int maxIndex = Integer.MIN_VALUE;
    Set<Integer> indices = new HashSet<>();
    for (ShardingKey key : keys) {
        int idx = key.getIndex();
        if (indices.contains(idx)) {
            throw new IllegalStateException("Duplicate sharding key index " + idx +
                    " found for model " + modelName);
        }
        indices.add(idx);
        if (idx > maxIndex) {
            maxIndex = idx;
        }
    }
    for (int i = 0; i <= maxIndex; i++) {
        if (!indices.contains(i)) {
            throw new IllegalStateException("Sharding key indices for model " + modelName +
                    " are not continuous. Missing index " + i);
        }
    }
}

private void check(String modelName) throws IllegalStateException {
    // Retrieve the sharding key indices for the given model
    List<Integer> indices = shardingKeyIndicesMap.get(modelName);
    if (indices == null) {
        // No sharding keys defined for this model; nothing to validate
        return;
    }

    // Verify that the indices are continuous starting from 0
    int expected = 0;
    for (Integer idx : indices) {
        if (idx == null || idx != expected) {
            throw new IllegalStateException("Sharding key indices for model " + modelName
                    + " are not continuous. Expected " + expected + " but found " + idx
                    + ". Full list: " + indices);
        }
        expected++;
    }
}

public byte readByte() throws IOException {
    if (pos >= count) {               // buffer exhausted, refill it
        count = in.read(buf);        // read into the buffer
        if (count == -1) {
            throw new EOFException("End of stream reached");
        }
        pos = 0;                     // reset position to start of buffer
    }
    return buf[pos++];                // return next byte from buffer
}

public byte readByte() throws IOException {
    if (curPos >= endPos) {
        int bytesRead = input.read(buffer);
        if (bytesRead <= 0) {
            throw new IOException("No more data available");
        }
        curPos = 0;
        endPos = bytesRead;
    }
    return buffer[curPos++];
}

public byte readByte() throws IOException {
    if (ptr >= count) {
        refill();                     // Refill the buffer if necessary
        if (count == 0) {              // No more data available
            throw new EOFException("End of stream");
        }
    }
    return buffer[ptr++];              // Return the next byte
}

public byte readByte() throws IOException {
    if (pos >= limit) {
        limit = in.read(buffer);
        pos = 0;
        if (limit <= 0) {
            throw new IOException("No more data available");
        }
    }
    return buffer[pos++];
}

public byte readByte() throws IOException {
    if (bufferPos >= bufferCount) {
        bufferCount = in.read(buffer);
        bufferPos = 0;
        if (bufferCount == -1) {
            throw new IOException("No more data available");
        }
    }
    return buffer[bufferPos++];
}

@Override
public Action inspect(AtmosphereResource r) {
    // Automatically suspend the resource for non-HTTP transports (e.g., WebSocket, SSE)
    if (r != null && r.getTransport() != null &&
        !AtmosphereResource.TRANSPORT.HTTP.equals(r.getTransport())) {
        try {
            r.suspend();
        } catch (Exception e) {
            // Ignore suspension failures (e.g., already suspended)
        }
    }
    return Action.CONTINUE;
}

@Override
public Action inspect(AtmosphereResource r){
    // Automatically suspend the resource if a transport is defined.
    if (r.getTransport() != null){
        r.suspend();
    }
    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    if (r == null) {
        return Action.CONTINUE;
    }
    // Suspend the resource if it's not already suspended.
    if (!r.isSuspended()) {
        try {
            // A negative timeout indicates no timeout; the transport will handle the suspension.
            r.suspend(-1);
        } catch (Exception e) {
            // Some transports may not support suspend; ignore the exception.
        }
    }
    return Action.CONTINUE;
}

@Override
public Action inspect(AtmosphereResource r) {
    if (r == null) {
        return Action.CONTINUE;
    }

    // Automatically suspend the resource based on its transport value
    String transport = r.getTransport();
    if (transport != null && transport.length() > 0) {
        r.suspend(); // uses the default suspend timeout
    }

    return Action.CONTINUE;
}

@Override public Action inspect(AtmosphereResource r){
    // Suspend the resource for transports that require it (WebSocket, SSE, Server-Side Streaming)
    String transport = r.getTransport();
    if (transport != null &&
        (transport.equalsIgnoreCase("ws") ||
         transport.equalsIgnoreCase("sse") ||
         transport.equalsIgnoreCase("streaming") ||
         transport.equalsIgnoreCase("eventsource"))) {
        if (!r.isSuspended()) {
            try {
                r.suspend(-1); // suspend indefinitely
            } catch (Exception ignore) {
                // ignore any exceptions during suspend
            }
        }
    }
    return Action.CONTINUE;
}

