public int compare(Object aObj1,Object aObj2){
    // Handle trivial cases
    if (aObj1 == aObj2) {
        return 0;
    }
    // Null handling: null is considered less than any non‑null object
    if (aObj1 == null) {
        return -1;
    }
    if (aObj2 == null) {
        return 1;
    }
    // Both objects are non‑null, attempt to compare them
    if (!(aObj1 instanceof Comparable) || !(aObj2 instanceof Comparable)) {
        throw new ClassCastException("Arguments are not comparable");
    }
    // Use raw Comparable to avoid generic type complications
    @SuppressWarnings("unchecked")
    Comparable<Object> comp1 = (Comparable<Object>) aObj1;
    // compareTo may throw ClassCastException if the argument types are incompatible
    return comp1.compareTo(aObj2);
}

