public int appendLoopOnAppenders(LoggingEvent event){
    int appendedCount = 0;
    if (appenders == null) {
        return 0;
    }
    // Iterate over all attached appenders and invoke doAppend on each
    for (Object o : appenders) {
        if (o == null) {
            continue;
        }
        try {
            ((Appender) o).doAppend(event);
            appendedCount++;
        } catch (Throwable t) {
            // If a single appender throws an exception, log it and continue
            // Note: logger is assumed to exist; otherwise replace with your own handling
            if (logger != null) {
                logger.warn("Exception occurred while appending to: " + o, t);
            }
        }
    }
    return appendedCount;
}

