public boolean containsKey(final Object key){
    if (size == 0) return false;
    int hash = (key == null) ? 0 : hash(key);
    Node<K,V>[] tab = table;
    for (Node<K,V> e = tab[hash & (tab.length - 1)]; e != null; e = e.next) {
        if (e.hash == hash && (key == e.key || (key != null && key.equals(e.key)))) {
            return true;
        }
    }
    return false;
}

