protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    // Append the byte array as a list of hex values.
    // The fieldName is typically not used because it has already been appended elsewhere.
    buffer.append('[');
    for (int i = 0; i < array.length; i++) {
        if (i > 0) {
            buffer.append(", ");
        }
        // Convert each byte to an unsigned int and format it as two hex digits.
        buffer.append(String.format("%02X", array[i] & 0xFF));
    }
    buffer.append(']');
}

protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    if (array == null) {
        if (fieldName != null && fieldName.length() > 0) {
            buffer.append(fieldName).append("=[null]");
        } else {
            buffer.append("[null]");
        }
        return;
    }
    if (fieldName != null && fieldName.length() > 0) {
        buffer.append(fieldName).append("=");
    }
    buffer.append("[");
    for (int i = 0; i < array.length; i++) {
        if (i > 0) {
            buffer.append(' ');
        }
        int value = array[i] & 0xFF;
        if (value < 16) {
            buffer.append('0');
        }
        buffer.append(Integer.toHexString(value).toUpperCase());
    }
    buffer.append("]");
}

