    // Detach the node from its neighbors.
    node.previous.next = node.next;
    node.next.previous = node.previous;

    // Help the garbage collector by clearing the node's links.
    node.next = null;
    node.previous = null;

    // Update the list size.
    size--;

    return true;
}

