            if (!reader.markSupported()) {
                // If mark/reset is not supported, we cannot push back the terminator.
                // In this case, we simply stop reading at the terminator.
                ch = reader.read();
                if (ch == -1) {
                    break;
                }
                char c = (char) ch;
                for (char t : terminators) {
                    if (c == t) {
                        return token.toString();
                    }
                }
                token.append(c);
            } else {
                reader.mark(1);
                ch = reader.read();
                if (ch == -1) {
                    break;
                }
                char c = (char) ch;
                for (char t : terminators) {
                    if (c == t) {
                        // push back the terminator for the next parse
                        reader.reset();
                        return token.toString();
                    }
                }
                token.append(c);
            }
        }
    } catch (IOException e) {
        throw new RuntimeException(e);
    }
    return token.toString();
}

private String parseToken(final char[] terminators) {
    // Assume the class has a String field `input` holding the text
    // and an int field `pos` indicating the current reading position.
    if (input == null || pos >= input.length()) {
        return "";
    }

    StringBuilder tokenBuilder = new StringBuilder();
    while (pos < input.length()) {
        char current = input.charAt(pos);

        // Check if the current character is one of the terminators.
        boolean isTerminator = false;
        for (char term : terminators) {
            if (current == term) {
                isTerminator = true;
                break;
            }
        }

        // If we hit a terminator, stop before consuming it.
        if (isTerminator) {
            break;
        }

        tokenBuilder.append(current);
        pos++;
    }

    return tokenBuilder.toString();
}

private String parseToken(final char[] terminators){
    // Return null if no terminators provided
    if (terminators == null || terminators.length == 0) {
        return null;
    }
    // Buffer used for parsing (assumed to be a class field)
    if (buffer == null || limit <= pos) {
        return null; // No more data to parse
    }

    StringBuilder sb = new StringBuilder();
    // Iterate until we hit a terminator or exhaust the buffer
    while (pos < limit) {
        char ch = buffer[pos++];
        // Check if this character is one of the terminators
        boolean isTerminator = false;
        for (char t : terminators) {
            if (ch == t) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            // Stop parsing when a terminator is found
            break;
        }
        sb.append(ch);
    }
    // Return the token only if we actually gathered characters
    return sb.length() > 0 ? sb.toString() : null;
}

