private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null){
        throw new IllegalArgumentException("bounds cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++){
        suffix.add(0);
    }
    long totalSum = 0L;
    for (int v : bounds){
        totalSum += v;
    }
    long running = 0L;
    for (int i = n - 1; i >= 0; i--){
        running += bounds.get(i);
        suffix.set(i, (int)running);
    }
    return new Pair<>(suffix, totalSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    java.util.List<Integer> suffix = new java.util.ArrayList<>(bounds.size());
    long totalSum = 0L;
    // Build suffix sums from the end
    for (int i = bounds.size() - 1; i >= 0; i--) {
        totalSum += bounds.get(i);
        suffix.add(0, Integer.valueOf((int) totalSum));
    }
    return new Pair<>(suffix, totalSum);
}

