private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Quick checks
    if (list == null || list.first == null) {
        return;
    }

    // Acquire locks on both lists in a fixed order to avoid deadlock
    Object firstLock = this;
    Object secondLock = list;
    if (System.identityHashCode(firstLock) > System.identityHashCode(secondLock)) {
        Object tmp = firstLock;
        firstLock = secondLock;
        secondLock = tmp;
    }

    synchronized (firstLock) {
        synchronized (secondLock) {
            // Attach list's nodes to the end of this list
            if (this.first == null) {
                // This list is empty
                this.first = list.first;
                this.last = list.last;
            } else {
                // Link the two lists
                this.last.next = list.first;
                list.first.prev = this.last;
                this.last = list.last;
            }
            // Update sizes
            this.size += list.size;

            // Clear the source list
            list.first = null;
            list.last = null;
            list.size = 0;
        }
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Grab the first node in the source list (assuming a sentinel header)
    ListNodeImpl<E> current = list.header.getNext();
    // Iterate until we reach the sentinel tail of the source list
    while (current != list.tail) {
        // Store the next node before we detach the current one
        ListNodeImpl<E> next = current.getNext();
        // Detach the current node from the source list
        list.removeListNode(current);
        // Attach the current node to this list
        this.addListNode(current);
        // Move to the next node in the source list
        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list.size == 0) {
        return;
    }
    ListNodeImpl<E> oldTailPrev = this.tail.prev;
    ListNodeImpl<E> firstNode = list.head.next;
    ListNodeImpl<E> lastNode = list.tail.prev;

    // link the moved nodes into this list
    oldTailPrev.next = firstNode;
    firstNode.prev = oldTailPrev;
    lastNode.next = this.tail;
    this.tail.prev = lastNode;

    // reset the source list to empty
    list.head.next = list.tail;
    list.tail.prev = list.head;
    list.size = 0;

    // update size of this list
    this.size += list.size; // after resetting, list.size is 0, so keep captured value
}

private void moveAllListNodes(DoublyLinkedList<E> list){
    // Traverse each node in the source list
    ListNode<E> node = list.getFirst();
    while (node != null) {
        ListNode<E> next = node.getNext();
        // Remove from the source list
        list.removeListNode(node);
        // Add to this (destination) list
        this.addListNode(node);
        // Proceed to next node
        node = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Nothing to move if the source list is null or empty
    if (list == null || list.size == 0) {
        return;
    }
    // If the destination list is empty just take ownership of the source list's nodes
    if (this.size == 0) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Otherwise splice the source list after the current tail
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    // Update the size of this list
    this.size += list.size;
    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null && prefix == null) {
        return true;
    }
    // If either is null (but not both), no match
    if (str == null || prefix == null) {
        return false;
    }
    // If we should ignore case, use regionMatches with ignoreCase flag
    if (ignoreCase) {
        if (prefix.length() > str.length()) {
            return false;
        }
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    } else {
        return str.startsWith(prefix);
    }
}

