    if (event == null) {
        return Filter.NEUTRAL;
    }
    String msg = event.getFormattedMessage();
    if (msg == null) {
        return Filter.NEUTRAL;
    }
    // If the message contains the string "SKIP", reject the event
    if (msg.contains("SKIP")) {
        return Filter.DENY;
    }
    // No string match – return NEUTRAL
    return Filter.NEUTRAL;
}

public int decide(LoggingEvent event) {
    // Retrieve the event message
    String message = event.getMessage();

    // If there is no message or it is empty, just return NEUTRAL
    if (message == null || message.isEmpty()) {
        return Filter.NEUTRAL;
    }

    // Example: if the message contains the word "ERROR" (case‑insensitive) we accept it
    if (message.toLowerCase().contains("error")) {
        return Filter.ACCEPT;
    }

    // In all other cases return NEUTRAL
    return Filter.NEUTRAL;
}

public int decide(LoggingEvent event) {
    // If no event or no message, don't apply any filtering.
    if (event == null) {
        return Filter.NEUTRAL;
    }

    // Attempt to retrieve the message; fall back on formatted message if available.
    String msg = event.getMessage();
    if (msg == null) {
        msg = event.getFormattedMessage();
    }

    // If there is no message content, return neutral.
    if (msg == null) {
        return Filter.NEUTRAL;
    }

    // 'targetString' is a field defined on this filter; if the message contains it,
    // consider the event accepted, otherwise leave it neutral.
    if (targetString != null && msg.contains(targetString)) {
        return Filter.ACCEPT;
    }

    // No match found – remain neutral.
    return Filter.NEUTRAL;
}

