public void putAllWriteable(BeanMap map){
    // Iterate over each property name in the provided map
    for (String name : map.keySet()) {
        // Retrieve the property descriptor to determine accessibility
        java.beans.PropertyDescriptor pd = map.getPropertyDescriptor(name);
        // Only copy properties that are both readable and writable
        if (pd != null
                && pd.getReadMethod() != null
                && pd.getWriteMethod() != null) {
            Object value = map.get(name); // read the value from the source map
            this.put(name, value);        // write the value into this map
        }
    }
}

public void putAllWriteable(BeanMap map) {
    for (Object key : map.keySet()) {
        if (map.isWritable(key) && this.isWritable(key)) {
            this.put(key, map.get(key));
        }
    }
}

