public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getModel().getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }
    // Select the row and all columns
    table.setRowSelectionInterval(row, row);
    table.setColumnSelectionInterval(0, table.getColumnCount() - 1);

    // Make the row visible in the viewport
    java.awt.Rectangle cellRect = table.getCellRect(row, 0, true);
    if (cellRect != null) {
        java.awt.Rectangle viewRect = pane.getViewport().getViewRect();
        if (!viewRect.contains(cellRect)) {
            pane.getViewport().scrollRectToVisible(cellRect);
        }
    }

    // Delay repaint to allow the table to update its painting
    javax.swing.Timer repaintTimer = new javax.swing.Timer(50, e -> {
        table.repaint();
        ((javax.swing.Timer) e.getSource()).stop();
    });
    repaintTimer.setRepeats(false);
    repaintTimer.start();
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (rowCount == 0) {
        return;
    }
    // Adjust row if out of bounds
    if (row < 0) {
        row = 0;
    } else if (row >= rowCount) {
        row = rowCount - 1;
    }

    // Select the specified row
    table.setRowSelectionInterval(row, row);

    // Ensure the row is visible within the viewport
    if (row >= 0) {
        Rectangle rect = table.getCellRect(row, 0, true);
        if (rect != null) {
            table.scrollRectToVisible(rect);
        }
    }

    // Delay repaint to allow the table to render the newly selected row
    javax.swing.Timer repaintTimer = new javax.swing.Timer(50, e -> {
        table.repaint();
        pane.revalidate();
        pane.repaint();
        ((javax.swing.Timer)e.getSource()).stop();
    });
    repaintTimer.setRepeats(false);
    repaintTimer.start();
}

