public void abbreviate(final int nameStart, final StringBuffer buf){
    if (name == null || buf == null) {
        return;
    }
    int len = name.length();
    int pos = Math.max(0, nameStart);
    while (pos < len) {
        // Skip any non‑alphanumeric characters (spaces, hyphens, dots, etc.)
        while (pos < len && !Character.isLetterOrDigit(name.charAt(pos))) {
            pos++;
        }
        if (pos >= len) {
            break;
        }
        // Append the first character of the word followed by a period
        buf.append(name.charAt(pos));
        buf.append('.');
        // Move to the next delimiter after the word
        while (pos < len && Character.isLetterOrDigit(name.charAt(pos))) {
            pos++;
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // The class must have a field `String name` representing the full name.
    // If `name` is null there's nothing to abbreviate.
    if (name == null) {
        return;
    }

    // Validate the requested start index.
    if (nameStart < 0 || nameStart > name.length()) {
        throw new IllegalArgumentException("nameStart is out of range: " + nameStart);
    }

    // Work on the substring that we need to abbreviate.
    final String sub = name.substring(nameStart);

    // Build an abbreviation by taking the first letter of each word.
    // Words are groups of alphanumeric characters separated by non‑alphanumerics
    // or by camel‑case boundaries.
    boolean startOfWord = true;
    for (int i = 0; i < sub.length(); i++) {
        final char ch = sub.charAt(i);

        if (Character.isLetterOrDigit(ch)) {
            if (startOfWord) {
                buf.append(Character.toUpperCase(ch));
                startOfWord = false;
            }
        } else {
            // Any non‑alphanumeric character signals the start of a new word.
            startOfWord = true;
        }
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    // Validate parameters
    if (buf == null || nameStart < 0 || nameStart > buf.length()) {
        return;
    }
    // Extract the name portion to abbreviate
    String name = buf.substring(nameStart);
    if (name.isEmpty()) {
        return;
    }
    // Build abbreviation by taking the first alphabetic/digit character
    // of each segment separated by '.', '_' or '-'
    StringBuilder abbr = new StringBuilder();
    int idx = 0;
    while (idx < name.length()) {
        // Skip separators
        while (idx < name.length()
                && (name.charAt(idx) == '.'
                    || name.charAt(idx) == '_'
                    || name.charAt(idx) == '-')) {
            idx++;
        }
        // Capture first non-separator character
        if (idx < name.length()
                && Character.isLetterOrDigit(name.charAt(idx))) {
            abbr.append(Character.toUpperCase(name.charAt(idx)));
        }
        // Advance to next separator
        while (idx < name.length()
                && (name.charAt(idx) != '.'
                    && name.charAt(idx) != '_'
                    && name.charAt(idx) != '-')) {
            idx++;
        }
    }
    // Append abbreviation to the buffer
    buf.append(abbr.toString());
}

