public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    for (Type bound : typeVariable.getBounds()) {
        if (bound instanceof Class<?>) {
            return bound;
        }
        if (bound instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) bound).getRawType();
            if (raw instanceof Class<?>) {
                return raw;
            }
        }
        if (bound instanceof WildcardType) {
            for (Type upper : ((WildcardType) bound).getUpperBounds()) {
                if (upper instanceof Class<?>) {
                    return upper;
                }
            }
        }
    }
    return Unknown.class;
}

public static Type resolveBound(TypeVariable<?> typeVariable) {
    if (typeVariable == null) {
        return Unknown.class;
    }
    Type[] bounds = typeVariable.getBounds();
    if (bounds == null || bounds.length == 0) {
        return Unknown.class;
    }
    for (Type bound : bounds) {
        if (bound instanceof Class<?>) {
            return (Class<?>) bound;
        }
        if (bound instanceof ParameterizedType) {
            return (ParameterizedType) bound;
        }
        if (bound instanceof WildcardType) {
            Type[] upperBounds = ((WildcardType) bound).getUpperBounds();
            if (upperBounds != null && upperBounds.length > 0) {
                for (Type upper : upperBounds) {
                    if (upper instanceof Class<?>) {
                        return (Class<?>) upper;
                    }
                    if (upper instanceof ParameterizedType) {
                        return (ParameterizedType) upper;
                    }
                }
            }
        }
        if (bound instanceof TypeVariable<?>) {
            Type resolved = resolveBound((TypeVariable<?>) bound);
            if (resolved != Unknown.class) {
                return resolved;
            }
        }
    }
    return Unknown.class;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() < 2) {
        return true;
    }
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2) && !graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    int n = vertices.size();
    if (n <= 1){
        return true;
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < n; i++){
        @SuppressWarnings("unchecked")
        V v1 = (V) arr[i];
        for (int j = i + 1; j < n; j++){
            @SuppressWarnings("unchecked")
            V v2 = (V) arr[j];
            if (!graph.containsEdge(v1, v2)){
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    int size = vertices.size();
    if (size < 2) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            if (!graph.containsEdge(vi, vj)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    // A single vertex or empty set is trivially a clique
    if (vertices == null || vertices.size() <= 1) {
        return true;
    }
    // Convert the set to an array for indexed access
    Object[] vertexArray = vertices.toArray();
    int n = vertexArray.length;
    for (int i = 0; i < n; i++) {
        V vi = (V) vertexArray[i];
        for (int j = i + 1; j < n; j++) {
            V vj = (V) vertexArray[j];
            // For an undirected graph, graph.containsEdge(vi, vj) is sufficient.
            // For a directed graph that still expects a clique in undirected sense,
            // we check both directions.
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null");
    }
    // An empty set or single vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            // Vertex not present in the graph
            return false;
        }
        for (V w : vertices) {
            if (!v.equals(w) && !graph.containsEdge(v, w)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    List<K> sorted = new ArrayList<>(keys);
    Collections.sort(sorted);
    for (K key : keys) {
        int idx = Collections.binarySearch(sorted, key);
        if (idx < 0) {
            idx = -idx - 1;
        }
        if (idx == 0) {
            lowerBounds.add(-1); // no lower bound found
        } else {
            lowerBounds.add(idx - 1); // index of maximum lower bound in sorted list
        }
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>(keys.size());
    for (K keyObj : keys) {
        if (keyObj == null) {
            result.add(0);
            continue;
        }
        int key = ((Integer) keyObj).intValue();
        int max = Integer.MIN_VALUE;
        for (K otherObj : keys) {
            if (otherObj == null) continue;
            int other = ((Integer) otherObj).intValue();
            if (other < key && other > max) {
                max = other;
            }
        }
        if (max == Integer.MIN_VALUE) {
            max = 0;
        }
        result.add(max);
    }
    return result;
}

