    for (int i = 0; i < keys.size(); i++) {
        lastIndexMap.put(keys.get(i), i);
    }
    java.util.List<Integer> result = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        result.add(lastIndexMap.get(key));
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        K current = keys.get(i);
        if (!(current instanceof Integer)) {
            result.add(null);
            continue;
        }
        int currVal = (Integer) current;
        Integer maxLower = null;
        for (K other : keys) {
            if (!(other instanceof Integer)) continue;
            int val = (Integer) other;
            if (val < currVal && (maxLower == null || val > maxLower)) {
                maxLower = val;
            }
        }
        result.add(maxLower);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }

    // Convert keys to integers for processing
    List<Integer> keyInts = new ArrayList<>();
    for (K k : keys) {
        if (k instanceof Integer) {
            keyInts.add((Integer) k);
        } else if (k instanceof Number) {
            keyInts.add(((Number) k).intValue());
        } else {
            // If the key cannot be converted, use a default value
            keyInts.add(0);
        }
    }

    // Create a sorted copy to perform binary search
    List<Integer> sorted = new ArrayList<>(keyInts);
    Collections.sort(sorted);

    // For each key, find the maximum lower bound
    for (int value : keyInts) {
        int idx = Collections.binarySearch(sorted, value);
        if (idx < 0) {
            idx = -idx - 1; // insertion point if not found
        }
        int lb = (idx > 0) ? sorted.get(idx - 1) : value;
        lowerBounds.add(lb);
    }

    return lowerBounds;
}

