/**
 * Consumes a single type from the descriptor starting at {@code index}.
 * For array types it skips the complete array descriptor.
 * The method returns the index after the processed type and increments {@code count} appropriately.
 */
private int consumeType(String descriptor, int index) {
    char c = descriptor.charAt(index);
    if (c == '[') {
        // Skip all leading '[' characters
        do {
            index++;
        } while (descriptor.charAt(index) == '[');
        // The type after the last '[' determines the slot count (always 1 for arrays)
        if (descriptor.charAt(index) == 'L') {
            // Skip until ';'
            do {
                index++;
            } while (descriptor.charAt(index) != ';');
        } else {
            // Primitive inside the array (J, D, or other)
            // Nothing else to skip, just one slot already counted
        }
        return index + 1; // move past the type terminator
    } else if (c == 'L') {
        // Object type: skip until ';'
        do {
            index++;
        } while (descriptor.charAt(index) != ';');
        return index + 1; // past ';'
    } else {
        // Primitive type
        return index + 1;
    }
}

