private List<Integer> computeUpperBounds(List<K> keys){
    // Create a sortable copy of the input list
    java.util.List<K> sorted = new java.util.ArrayList<>(keys);
    // Sort using the natural ordering of K (must be Comparable)
    java.util.Collections.sort(sorted);
    // Prepare the result list
    java.util.List<Integer> upperBounds = new java.util.ArrayList<>(keys.size());
    // For each original key, find the first index in the sorted list that is > key
    for (K key : keys) {
        int lo = 0;
        int hi = sorted.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            // Compare the middle element with the key
            @SuppressWarnings("unchecked")
            int cmp = ((Comparable<K>)sorted.get(mid)).compareTo(key);
            if (cmp <= 0) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        // lo is now the upper bound index for this key
        upperBounds.add(lo);
    }
    return upperBounds;
}

