public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Treat path as a file or directory path
    java.nio.file.Path base = java.nio.file.Path.of(path);
    java.nio.file.Path baseDir = base.getParent();
    if (baseDir == null) {
        // path has no parent (root or just a file name)
        baseDir = base;
    }
    // Resolve relative path against base directory and normalize
    java.nio.file.Path resolved = baseDir.resolve(relativePath).normalize();
    // Convert to a string with forward slashes for Java folder separation
    return resolved.toString().replace('\\', '/');
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    java.nio.file.Path p;
    try {
        p = java.nio.file.Paths.get(path);
    } catch (Exception e) {
        // If the path cannot be parsed, just concatenate with a slash
        return path.endsWith("/") ? path + relativePath : path + "/" + relativePath;
    }
    java.nio.file.Path base = p.getParent();
    if (base == null) {
        // If there is no parent (e.g., a single file name), use the current directory
        base = java.nio.file.Paths.get(".");
    }
    java.nio.file.Path resolved = base.resolve(relativePath).normalize();
    String result = resolved.toString();
    // Convert OS-specific separators to '/' to match the input format
    if (java.io.File.separatorChar != '/') {
        result = result.replace(java.io.File.separatorChar, '/');
    }
    return result;
}

public static String applyRelativePath(String path, String relativePath){
    if(path == null || relativePath == null){
        throw new IllegalArgumentException("path and relativePath must not be null");
    }
    String separator = "/";
    // split the base path into parts, ignoring empty segments caused by leading/trailing '/'
    java.util.List<String> baseParts = new java.util.ArrayList<>();
    for(String part : path.split(separator)){
        if(!part.isEmpty()){
            baseParts.add(part);
        }
    }
    // split the relative path into parts
    for(String part : relativePath.split(separator)){
        if(part.isEmpty() || part.equals(".")){
            continue; // stay in the same directory
        } else if(part.equals("..")){
            if(!baseParts.isEmpty()){
                baseParts.remove(baseParts.size() - 1);
            }
        } else {
            baseParts.add(part);
        }
    }
    // rebuild the path
    StringBuilder result = new StringBuilder();
    if(path.startsWith(separator)){
        result.append(separator);
    }
    result.append(String.join(separator, baseParts));
    // Ensure root "/" stays as "/", not empty
    if(result.length() == 0){
        result.append(separator);
    }
    return result.toString();
}

