    // Resolve virtual nodes to their real counterparts
    if (start.isVirtual()) {
        start = start.getReal();
    }
    if (end.isVirtual()) {
        end = end.getReal();
    }

    // If either of the nodes became null during resolution, no edge can be created
    if (start == null || end == null) {
        return null;
    }

    return new Edge(start, end);
}

