protected void append(LoggingEvent event){
    String message = event.getFormattedMessage();
    // Assume `clients` is a thread‑safe collection holding all connected sockets
    synchronized (clients) {
        // Iterate over a copy to safely modify the original collection
        for (Socket client : new java.util.ArrayList<>(clients)) {
            try {
                java.io.PrintWriter out = new java.io.PrintWriter(
                        client.getOutputStream(), true);
                out.println(message);
            } catch (java.io.IOException e) {
                // Remove the faulty client and close its socket
                clients.remove(client);
                try {
                    client.close();
                } catch (java.io.IOException ignore) {
                }
            }
        }
    }
}

protected void append(LoggingEvent event) {
    String message = event.getFormattedMessage();
    for (Client client : clients) {        // clients is the collection of connected clients
        try {
            client.send(message);          // write the message to the client
            client.flush();                // ensure it's transmitted immediately
        } catch (Exception e) {
            // If sending to a client fails, we ignore to keep other clients
            // affected. In a real implementation you might log this error.
        }
    }
}

protected void append(LoggingEvent event) {
    String renderedMessage = event.getRenderedMessage();
    for (PrintWriter out : clientWriters) {
        try {
            out.println(renderedMessage);
            out.flush();
        } catch (Exception e) {
            // Ignore failures for individual clients
        }
    }
}

protected void append(LoggingEvent event) {
    String msg = event.getMessage() == null ? "" : event.getMessage().toString();
    synchronized (clients) {
        Iterator<Socket> it = clients.iterator();
        while (it.hasNext()) {
            Socket s = it.next();
            try {
                OutputStream os = s.getOutputStream();
                os.write((msg + "\n").getBytes("UTF-8"));
                os.flush();
            } catch (IOException e) {
                it.remove();
                try { s.close(); } catch (IOException ignored) {}
            }
        }
    }
}

