    // repeated field and update the internal state accordingly.

    // The field descriptor should already be set for the tag that was just read.
    // If it is null we cannot make a decision.
    if (fieldDescriptor == null) {
        packedField = false;
        return;
    }

    // Check that the wire type of the current tag is LENGTH_DELIMITED (2).
    // Repeated primitive fields (non-message) use this wire type when packed.
    boolean isLengthDelimited = (tag & 0x7) == WireFormat.WIRETYPE_LENGTH_DELIMITED;

