    // For packed fields, nestedReader or other logic will treat the following
    // bytes as a single composite message.
    if (isLengthDelimited && fieldDescriptor.isRepeated() &&
        fieldDescriptor.getJavaType() != JavaType.MESSAGE) {
        packedField = true;
        // Fast-path: read the length of the packed buffer so that subsequent
        // read operations can be satisfied from it.
        packedLength = readRawVarint32();
    } else {
        packedField = false;
        packedLength = 0;
    }
}

