public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            // Reached EOF; no more tags.
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Malformed varint tag");
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift <= 32) {
        int b = input.read();
        if (b == -1) {
            return 0;   // EOF reached before a tag starts
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;   // completed varint tag
        }
        shift += 7;
    }
    throw new IOException("Malformed tag: varint too long");
}

public int readTag() throws IOException {
    int firstByte = input.read();
    if (firstByte == -1) {
        // Reached EOF; no more tags.
        return 0;
    }
    if ((firstByte & 0x80) == 0) {
        // Single-byte varint.
        return firstByte;
    }
    int tag = firstByte & 0x7F;
    int shift = 7;
    while (true) {
        int nextByte = input.read();
        if (nextByte == -1) {
            // Unexpected EOF while reading a multi-byte tag.
            return 0;
        }
        tag |= (nextByte & 0x7F) << shift;
        if ((nextByte & 0x80) == 0) {
            break;
        }
        shift += 7;
    }
    return tag;
}

public int readTag() throws IOException {
    if (isAtEnd()) {
        return 0;
    }
    return readRawVarint32();
}

